/* One source library linked to clinical decisions, separate from hospital protocol approval. */
(()=>{
let query='';
for(const [k,r]of Object.entries(FNClinicalGuidelines.sources))FNKnowledge.references[k==='fn'?'idsa':k]={...r};
function page(){const g=FNClinicalGuidelines,rows=Object.entries(g.sources).filter(([,r])=>JSON.stringify(r).toLowerCase().includes(query.toLowerCase()));return header('Guidelines & clinical references','Source-linked FN guidance, dosing references and local adoption status.',`<button class="btn" onclick="go('Resources')">Resources</button>`)+`<section class="panel"><h2>Clinical source register</h2><p>Adult cancer-associated FN training decision support. Each source retains its own date, scope and recommendation location. A linked guideline is not a hospital-approved protocol.</p><div class="actions"><button class="btn" onclick="fnWorkbook.tab('MASCC Index')">MASCC Index</button><button class="btn" onclick="fnWorkbook.tab('Renal reference')">Renal references</button><button class="btn" onclick="fnWorkbook.tab('Data Dictionary')">Data dictionary</button><button class="btn" onclick="fnDyn.tab('Local protocol');go('Dynamic reassessment')">Hospital local protocol</button><button class="btn" onclick="fnGuidelines.export()">Export guideline register</button></div><label class="field">Search guidelines<input value="${esc(query)}" placeholder="IDSA, AGIHO, outpatient, resistance…" onchange="fnGuidelines.search(this.value)"></label></section><div class="abx-guideline-grid">${rows.map(([k,r])=>`<article class="panel"><span class="intake-eyebrow">${esc(r.version)}</span><h2>${esc(r.title)}</h2><p>${esc(r.scope)}</p><p><b>Source location:</b> ${esc(r.location)}</p><p><b>Status:</b> ${esc(r.status)}</p><p class="mini">Last source check: ${g.checked}</p><a class="btn" href="${esc(r.url)}" target="_blank" rel="noopener">Read original guideline</a></article>`).join('')}</div><section class="panel"><h2>How the references support the application</h2>${g.applications.map(a=>`<article class="stage"><h3>${esc(a.name)}</h3><p>${esc(a.summary)}</p><p class="mini">${a.sources.map(k=>`<a href="${g.sources[k].url}" target="_blank" rel="noopener">${esc(g.sources[k].title)} (${esc(g.sources[k].version)})</a>`).join(' · ')}</p></article>`).join('')}<p>Guideline selection principles, FDA product dosing and institutional infusion examples have different scopes. Differences are retained for local reconciliation. The application does not calculate CISNE, apply an automatic antibiotic stop rule, or treat a selected reference as clinical authorization.</p></section><section class="panel"><h2>Drug-specific dosing references</h2><p>These support the existing gated dose references; they do not independently establish an FN indication or local formulary approval.</p>${Object.entries(FNAction.refs).filter(([k])=>!['fn','outpatient','amr'].includes(k)).map(([,r])=>`<p><a href="${esc(r.url)}" target="_blank" rel="noopener">${esc(r.title)}</a></p>`).join('')}</section>`}
window.fnGuidelines={open(){go('Clinical guidelines');window.scrollTo(0,0)},search(v){query=v;render()},export(){download('FN_clinical_guidelines_register.json',FNClinicalGuidelines)}};
const previous=render;render=function(){previous();if(view==='Clinical guidelines')document.querySelector('#app').innerHTML=page();if(view==='Workbook database'){const tabs=document.querySelector('#app .tabs');tabs?.insertAdjacentHTML('afterbegin','<button onclick="fnGuidelines.open()">FN guidelines & evidence</button>')}};
})();
